package org.icu.sepsis.deterioration;
import static org.junit.jupiter.api.Assertions.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import org.icu.sepsis.config.RuleConfig;import org.icu.sepsis.domain.Domain.*;import org.icu.sepsis.sepsis.Icu05Rules;
class FourClinicalFeaturesTest {
 final Instant now=Instant.parse("2026-11-20T10:00:00Z");Patient patient(){var p=new Patient();p.id="synthetic";p.encounterId="stay";p.department="TEST";return p;}
 Observation row(String code,double value,String unit,Instant time){var o=new Observation();o.patientId="synthetic";o.encounterId="stay";o.department="TEST";o.parameterCode=code;o.value=value;o.unit=unit;o.eventTime=time;o.qualityStatus="valid";return o;}
 Map<String,Object> item(Map<String,Object> packet,String code){return ((List<Map<String,Object>>)packet.get("items")).stream().filter(i->code.equals(i.get("code"))).findFirst().orElseThrow();}
 @Test void qualityDistinguishesReadyConflictStaleAndMissingWithoutCrossStayReuse(){var rows=new ArrayList<Observation>();rows.add(row("HR",80,"bpm",now.minusSeconds(600)));rows.add(row("HR",90,"bpm",now.minusSeconds(600)));rows.add(row("LACTATE",2,"mmol/L",now.minus(Duration.ofHours(8))));var other=row("CREA",100,"μmol/L",now);other.encounterId="other";rows.add(other);var q=DataQualityService.evaluate(patient(),now,rows,true,new RuleConfig());assertEquals("review",item(q,"HR").get("status"));assertEquals("stale",item(q,"LACTATE").get("status"));assertEquals("missing",item(q,"CREA").get("status"));assertEquals(24,((List<?>)item(q,"HR").get("hours")).size());}
 @Test void sourceFailureIsNotAnEmptyNormalDashboard(){var q=DataQualityService.evaluate(patient(),now,List.of(),false,new RuleConfig());assertTrue(((List<Map<String,Object>>)q.get("items")).stream().allMatch(i->"unavailable".equals(i.get("status"))));}
 @Test void unconfirmedUnitsAndFutureTimesCannotBecomeUsable(){var lac=row("LACTATE",1.2,"mmol/L",now);lac.encounterLinkStatus="unconfirmed";var weight=row("WEIGHT",70,"",now);var hr=row("HR",80,"bpm",now.plusSeconds(1));var q=DataQualityService.evaluate(patient(),now,List.of(lac,weight,hr),true,new RuleConfig());for(String code:List.of("LACTATE","WEIGHT","HR"))assertEquals("review",item(q,code).get("status"));}
 @Test void configuredFreshnessIsReusedAndNumericOutliersAreRejected(){var cfg=new RuleConfig();cfg.setFreshMinutes(60);var q=DataQualityService.evaluate(patient(),now,List.of(row("HR",80,"bpm",now.minusSeconds(3600)),row("SPO2",999,"%",now)),true,cfg);assertEquals("ready",item(q,"HR").get("status"));assertEquals("review",item(q,"SPO2").get("status"));}
 @Test void medicationDictionaryUsesBoundariesAndDoesNotClaimCompleteCoverage(){assertEquals("NSAIDs",RenalMedicationReviewService.group("布洛芬注射液"));assertEquals("利尿剂",RenalMedicationReviewService.group("Furosemide Injection"));assertNull(RenalMedicationReviewService.group("notfurosemidecompound"));assertNull(RenalMedicationReviewService.group("0.9%氯化钠注射液"));}
 @Test void stoppedAndUnclassifiedRecordsRemainReviewCluesAndFutureEventsAreExcluded(){var e=new Icu05Rules.Evidence();var d=new Icu05Rules.Drug();d.sourceId="synthetic-drug";d.start=now.minus(Duration.ofDays(10));d.items.add(new Icu05Rules.DrugItem("呋塞米",null));d.actions.add(new Icu05Rules.Action(now.minusSeconds(300),"stop"));e.drugs.add(d);var future=new Icu05Rules.Drug();future.start=now.plusSeconds(1);future.items.add(new Icu05Rules.DrugItem("阿米卡星",null));e.drugs.add(future);var q=RenalMedicationReviewService.evaluate(patient(),now.minus(Duration.ofDays(7)),now,e,"incomplete",Map.of());var meds=(List<Map<String,Object>>)q.get("medications");assertEquals(1,meds.size());assertEquals("停止记录",meds.get(0).get("lastAction"));assertFalse(meds.get(0).containsKey("active"));assertFalse(meds.get(0).containsKey("recommendedDose"));assertEquals("incomplete",q.get("sourceStatus"));}
}
